package com.aoo.bcg.common.cache;import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ProtectedLookupCacheTest{@Test void negativeResultIsCachedAndConcurrentMissesSingleFlight()throws Exception{var cache=new ProtectedLookupCache<String,String>(new AuthoritativeTimeSource(Clock.fixed(Instant.now(),ZoneOffset.UTC)),Duration.ofMinutes(5),Duration.ofSeconds(20),100);var loads=new AtomicInteger();var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(16);List<Future<Optional<String>>>jobs=new ArrayList<>();for(int i=0;i<100;i++)jobs.add(pool.submit(()->{start.await();return cache.get("missing",key->{loads.incrementAndGet();return Optional.empty();});}));start.countDown();for(var job:jobs)assertTrue(job.get().isEmpty());pool.shutdown();assertEquals(1,loads.get());assertTrue(cache.get("missing",key->{loads.incrementAndGet();return Optional.of("unexpected");}).isEmpty());assertEquals(1,loads.get());}}
